def build_instance(rng):
    integer_count = rng.randint(2, 5)
    fixed_sum = rng.randint(10, 20)
    parameters = {"integer_count": integer_count, "fixed_sum": fixed_sum}

    # Generate all possible combinations of positive integers that sum to fixed_sum
    answer = set()
    for r in range(1, integer_count + 1):
        for combo in combinations_with_replacement(range(1, fixed_sum), r):
            if sum(combo) == fixed_sum:
                answer.add(tuple(sorted(combo)))

    # Verify by enumerating all possible combinations
    check = set()
    for r in range(1, integer_count + 1):
        for combo in combinations_with_replacement(range(1, fixed_sum), r):
            if sum(combo) == fixed_sum:
                check.add(tuple(sorted(combo)))

    return parameters, answer, check
